import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int totalStates = 0;
    static int[] bitCount = new int[250];
    static int[] position = new int[250];
    static int[][] f = new int[10][250];
    static List<List<Integer>> layerGroups = new ArrayList<>();
    static Map<Pair, Integer> cache = new HashMap<>();

    static class Pair {
        int layer;
        long mask;

        Pair(int layer, long mask) {
            this.layer = layer;
            this.mask = mask;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return layer == pair.layer && mask == pair.mask;
        }

        @Override
        public int hashCode() {
            return Objects.hash(layer, mask);
        }
    }

    static int fastPower(int base, int exponent) {
        long result = 1;
        long b = base;
        long e = exponent;
        while (e > 0) {
            if ((e & 1) == 1) result = (result * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return (int) result;
    }

    static int recurse(int layer, long mask) {
        if (mask == 0) return 0;
        if (layer == n) return 1;
        Pair key = new Pair(layer, mask);
        if (cache.containsKey(key)) return cache.get(key);

        totalStates++;
        int total = 0;
        int maxSubsetMask = (1 << n) - 1;
        for (int subsetMask = 1; subsetMask <= maxSubsetMask; subsetMask++) {
            long next_mask = 0;
            for (int kIdx = 0; kIdx < layerGroups.get(layer).size(); kIdx++) {
                int prevVal = layerGroups.get(layer).get(kIdx);
                if ((mask & (1L << kIdx)) == 0) continue;
                for (int l = 0; l < n; l++) {
                    if ((subsetMask & (1 << l)) != 0 && (prevVal & (1 << l)) == 0) {
                        next_mask |= 1L << position[prevVal | (1 << l)];
                    }
                }
            }
            long fVal = f[layer][subsetMask];
            total = (int) ((total + (long) fVal * recurse(layer + 1, next_mask)) % MOD);
        }
        cache.put(key, total);
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        int inv100 = fastPower(100, MOD - 2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                String[] parts = br.readLine().split(" ");
                int P = Integer.parseInt(parts[j]);
                int p1 = (int) ((long) P * inv100 % MOD);
                int p0 = (MOD + 1 - p1) % MOD;
                for (int k = 0; k < (1 << j); k++) {
                    f[i][k | (1 << j)] = (int) ((long) f[i][k] * p1 % MOD);
                    f[i][k] = (int) ((long) f[i][k] * p0 % MOD);
                }
            }
        }
        for (int i = 0; i < (1 << n); i++) {
            bitCount[i] = Integer.bitCount(i);
        }
        for (int i = 0; i < (1 << n); i++) {
            while (layerGroups.size() <= bitCount[i]) {
                layerGroups.add(new ArrayList<>());
            }
            layerGroups.get(bitCount[i]).add(i);
            position[i] = layerGroups.get(bitCount[i]).size() - 1;
        }
        System.out.println(recurse(0, 1L));
    }
}
